package org.apache.commons.math.stat.descriptive.moment;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.exception.NullArgumentException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.stat.descriptive.AbstractStorelessUnivariateStatistic;
import org.apache.commons.math.stat.descriptive.WeightedEvaluation;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for Variance.copy(Variance, Variance)
 */
public class Variance_copy_TriageGen2Test {

    @Test
    public void testCopy_Success() {
        // Setup source
        Variance source = new Variance(true);
        double[] data = {1.0, 2.0, 3.0};
        source.evaluate(data);

        // Setup destination
        Variance dest = new Variance();

        // Execute
        Variance.copy(source, dest);

        // Verify results
        Assert.assertEquals("Bias corrected status should match", source.isBiasCorrected(), dest.isBiasCorrected());
        Assert.assertEquals("Resulting variance should match", source.getResult(), dest.getResult(), 1e-10);
        Assert.assertEquals("N count should match", source.getN(), dest.getN());

        // Verify internal state via a second copy to ensure deep copy of moment
        Variance dest2 = new Variance();
        Variance.copy(source, dest2);
        Assert.assertEquals("Deep copy of moment should match", dest.getResult(), dest2.getResult(), 1e-10);
    }








}

